var BrowserWindow = require('sketch-module-web-view');
var { getWebview, initializeBridge } = require('./plugin/bridge');

var WEBVIEW_ID = 'sketch-agent.webview';

function openChatPanel() {
  var existingWindow = getWebview();
  if (existingWindow) {
    existingWindow.show();
    existingWindow.focus();
    return;
  }

  var options = {
    identifier: WEBVIEW_ID,
    width: 380,
    height: 640,
    show: false,
    title: 'AI Chat',
    titleBarStyle: 'hidden',
    remembersWindowFrame: true,
    resizable: true,
    minimizable: true,
    alwaysOnTop: true,
    hidesOnDeactivate: false,
    hasShadow: false,
    backgroundColor: '#FFFFFF',
    webPreferences: {
      devTools: true,
    },
  };

  var browserWindow = new BrowserWindow(options);

  initializeBridge(browserWindow);

  browserWindow.once('ready-to-show', function() {
    var threadDictionary = NSThread.mainThread().threadDictionary();
    var panel = threadDictionary[WEBVIEW_ID];
    if (panel) {
      panel.standardWindowButton(NSWindowCloseButton).setHidden(true);
      panel.standardWindowButton(NSWindowMiniaturizeButton).setHidden(true);
      panel.standardWindowButton(NSWindowZoomButton).setHidden(true);
    }
    browserWindow.show();
  });

  browserWindow.loadURL(require('../resources/webview.html'));
}

function onShutdown() {
  var existingWindow = getWebview();
  if (existingWindow) {
    existingWindow.close();
  }
}

function onQuit() {
  var threadDictionary = NSThread.mainThread().threadDictionary();
  var panel = threadDictionary[WEBVIEW_ID];
  if (panel) {
    panel.close();
  }
}

module.exports = {
  openChatPanel: openChatPanel,
  onShutdown: onShutdown,
  onQuit: onQuit,
};
