function executeCreate(document, parent, command) {
  var sketch = require('sketch/dom');
  var createdLayers = [];

  for (var i = 0; i < command.operations.length; i++) {
    var op = command.operations[i];
    var params = op.params || {};
    var layer;

    var opType = (op.type || '').toLowerCase();

    switch (opType) {
      case 'create_rectangle':
        var style = { fills: params.fillColor ? [{ fillType: 'Color', color: params.fillColor }] : [] };
        if (params.borderColor || params.borderThickness) {
          style.borders = [{
            fillType: 'Color',
            color: params.borderColor || '#000000',
            thickness: params.borderThickness || 1,
          }];
        }
        if (params.shadowColor) {
          style.shadows = [{
            color: params.shadowColor || '#00000040',
            offsetX: params.shadowOffsetX || 0,
            offsetY: params.shadowOffsetY || 2,
            blur: params.shadowBlur || 4,
            spread: 0,
          }];
        }
        if (params.opacity !== undefined) {
          style.opacity = Math.max(0, Math.min(1, params.opacity));
        }
        layer = new sketch.ShapePath({
          name: params.name || 'Rectangle',
          frame: { x: params.x || 0, y: params.y || 0, width: params.width || 100, height: params.height || 50 },
          style: style,
          parent: parent,
        });
        if (params.cornerRadius && layer.points) {
          layer.points.forEach(function(p) { p.cornerRadius = params.cornerRadius; });
        }
        createdLayers.push(layer);
        break;
      case 'create_text':
        layer = new sketch.Text({
          name: params.name || 'Text', text: params.text || 'Text',
          frame: { x: params.x || 0, y: params.y || 0, width: params.width || 200, height: params.height || 40 },
          style: { fontSize: params.fontSize || 14, fontFamily: params.fontFamily || 'System Font', textColor: params.color || '#000000', alignment: params.alignment || 'left' },
          parent: parent,
        });
        createdLayers.push(layer);
        break;
      case 'create_icon':
        module.exports._pendingIcons = module.exports._pendingIcons || [];
        var iconParent = parent;
        module.exports._pendingIcons.push({
          name: params.name || 'Icon',
          iconName: params.iconName || 'circle',
          color: params.color || '#000000',
          size: params.size || 24,
          x: params.x || 0, y: params.y || 0,
          parentId: iconParent && iconParent.id ? iconParent.id : null,
        });
        break;
      case 'create_image':
        layer = new sketch.Image({
          name: params.name || 'Image',
          frame: { x: params.x || 0, y: params.y || 0, width: params.width || 100, height: params.height || 100 },
          parent: parent,
        });
        createdLayers.push(layer);
        break;
      case 'create_group':
        var group = new sketch.Group({
          name: params.name || 'Group',
          frame: { x: params.x || 0, y: params.y || 0, width: params.width || 200, height: params.height || 200 },
          parent: parent,
        });
        if (params.children && Array.isArray(params.children)) {
          for (var j = 0; j < params.children.length; j++) {
            executeCreate(document, group, { operations: [params.children[j]] });
          }
        }
        createdLayers.push(group);
        group.adjustToFit();
        break;
      default:
        return { action: 'create', error: 'Unknown create operation: ' + opType };
    }
  }

  return { action: 'create', createdLayers: createdLayers.map(function(l) { return { id: l.id, name: l.name, type: l.type }; }) };
}

function getTargetParent(document, command) {
  var parent;
  if (command.target) {
    parent = document.getLayerWithID(command.target);
  }
  if (!parent) {
    parent = document.selectedPage;
  }
  return parent;
}

module.exports = { executeCreate: executeCreate, getTargetParent: getTargetParent };
