var modify = require('./modify');
var create = require('./create');
var arrange = require('./arrange');

function executeCommands(document, commands, layerMap) {
  var results = [];
  for (var i = 0; i < commands.length; i++) {
    var cmd = commands[i];
    var action = (cmd.action || '').toLowerCase();
    var result;
    switch (action) {
      case 'modify':
        result = modify.executeModify(document, cmd, layerMap);
        break;
      case 'create':
        var parent = create.getTargetParent(document, cmd);
        result = create.executeCreate(document, parent, cmd);
        break;
      case 'delete':
        result = arrange.executeDelete(document, cmd);
        break;
      case 'arrange':
        result = arrange.executeArrange(document, cmd);
        break;
      default:
        result = { action: cmd.action, target: cmd.target, error: 'Unknown action: ' + String(cmd.action) };
    }
    results.push(result);
  }
  return results;
}

module.exports = { executeCommands: executeCommands };
