function saveSnapshot() {
  var sketch = require('sketch/dom');
  var document = sketch.getSelectedDocument();
  if (!document) return false;
  try {
    var layers = document.selectedPage.layers;
    var snapshot = {
      documentId: document.id, pageId: document.selectedPage.id,
      layerCount: layers ? layers.length : 0, timestamp: Date.now(),
    };
    return true;
  } catch (e) {
    console.error('Snapshot save failed:', e);
    return false;
  }
}

function undoLastOperation() {
  var sketch = require('sketch/dom');
  var document = sketch.getSelectedDocument();
  if (!document) return false;
  try {
    document.selectedPage.sketchObject.undoManager().undo();
    return true;
  } catch (e) {
    console.error('Undo failed:', e);
    return false;
  }
}

module.exports = { saveSnapshot: saveSnapshot, undoLastOperation: undoLastOperation };
