function createAdapter(providerOverride, configOverride) {
  var settings = require('../storage/settings');
  var config = configOverride || settings.getAllSettings();

  if (providerOverride) {
    config = Object.assign({}, config);
    config.provider = providerOverride;
  }

  var adapterModule;
  switch (config.provider) {
    case 'openai':
      adapterModule = require('./openai-adapter');
      break;
    case 'kimi':
      adapterModule = require('./kimi-adapter');
      break;
    case 'claude':
      adapterModule = require('./claude-adapter');
      break;
    case 'deepseek':
      adapterModule = require('./deepseek-adapter');
      break;
    case 'glm':
      adapterModule = require('./glm-adapter');
      break;
    default:
      adapterModule = require('./openai-adapter');
  }

  return new adapterModule(config);
}

var adapterCache = null;

function getAdapter() {
  if (!adapterCache) {
    adapterCache = createAdapter();
  }
  return adapterCache;
}

function invalidateCache() {
  adapterCache = null;
}

module.exports = {
  createAdapter: createAdapter,
  getAdapter: getAdapter,
  invalidateCache: invalidateCache,
};
