function executeArrange(document, command) {
  var targetId = command.target;
  var layer = document.getLayerWithID(targetId);
  if (!layer) throw new Error('Target layer not found: ' + targetId);

  for (var i = 0; i < command.operations.length; i++) {
    var op = command.operations[i];
    switch (op.type) {
      case 'move_to_front': layer.moveToFront(); break;
      case 'move_to_back': layer.moveToBack(); break;
      case 'move_forward': layer.moveForward(); break;
      case 'move_backward': layer.moveBackward(); break;
    }
  }
  return { action: 'arrange', target: targetId };
}

function executeDelete(document, command) {
  var targetId = command.target;
  var layer = document.getLayerWithID(targetId);
  if (!layer) throw new Error('Target layer not found: ' + targetId);
  layer.remove();
  return { action: 'delete', target: targetId };
}

module.exports = { executeArrange: executeArrange, executeDelete: executeDelete };
